const String androidMicrophoneProviderSource =
    r'''import 'package:flutter/services.dart';
import 'package:mini_program_contracts/mini_program_contracts.dart';
import 'package:mini_program_sdk/mini_program_sdk.dart';

/// Host-owned adapter generated by `miniprogram host capability init microphone`.
class AppAndroidMicrophoneProvider implements MiniProgramMicrophoneProvider {
  const AppAndroidMicrophoneProvider();
  static const _channel = MethodChannel('mini_program/microphone');
  static final _started = <String, void Function()>{};

  @override
  Future<MiniProgramMicrophoneResult> record(MiniProgramMicrophoneRequest request,
      {required void Function() onStarted}) async {
    _started[request.recordingId] = onStarted;
    _channel.setMethodCallHandler((call) async {
      if (call.method == 'recordingStarted' && call.arguments is Map) {
        final id = (call.arguments as Map)['recordingId'];
        if (id is String) _started.remove(id)?.call();
      }
    });
    Map<String, dynamic>? response;
    try {
      response = await _channel.invokeMapMethod<String, dynamic>('record', {
        'recordingId': request.recordingId, 'miniProgramId': request.miniProgramId,
        'maxDurationSeconds': request.maxDurationSeconds, 'maxBytes': request.maxBytes,
      });
      if (response == null) throw const FormatException('Missing recording metadata.');
      return MiniProgramMicrophoneResult.fromJson(response);
    } on MissingPluginException {
      throw const MiniProgramMicrophoneException(errorCode: MiniProgramErrorCodes.microphoneUnavailable,
        message: 'The Android microphone provider is not installed.');
    } on PlatformException catch (error) {
      final code = const {'microphone_unavailable', 'microphone_permission_denied',
        'microphone_permission_denied_permanently', 'microphone_request_in_progress',
        'microphone_recording_cancelled', 'microphone_invalid_request',
        'microphone_limit_exceeded', 'microphone_storage_unavailable',
        'microphone_operation_failed'}.contains(error.code)
          ? error.code : MiniProgramErrorCodes.microphoneOperationFailed;
      throw MiniProgramMicrophoneException(errorCode: code,
        message: 'Android microphone recording did not complete.');
    } catch (_) {
      final ref = response?['mediaRef'];
      if (ref is String) {
        try { await releaseMedia(MiniProgramMediaReleaseRequest(miniProgramId: request.miniProgramId, mediaRef: ref)); }
        catch (_) { /* Malformed native results are cleaned up best effort. */ }
      }
      throw const MiniProgramMicrophoneException(errorCode: MiniProgramErrorCodes.microphoneInvalidResult,
        message: 'Android returned invalid recording metadata.');
    } finally { _started.remove(request.recordingId); }
  }

  @override
  Future<bool> stop(String recordingId, {bool background = false}) =>
      _control('stop', recordingId, background: background);
  @override
  Future<bool> cancel(String recordingId) => _control('cancel', recordingId);
  Future<bool> _control(String method, String id, {bool background = false}) async {
    try { return await _channel.invokeMethod<bool>(method, {'recordingId': id, 'background': background}) ?? false; }
    on MissingPluginException { return false; }
    on PlatformException { return false; }
  }

  @override
  Future<MiniProgramMediaPreviewResult> loadPreview(MiniProgramMediaPreviewRequest request) async {
    throw const MiniProgramMediaException(errorCode: MiniProgramErrorCodes.mediaInvalidResult,
      message: 'Voice recordings use audio playback rather than image previews.');
  }
  @override
  Future<bool> releaseMedia(MiniProgramMediaReleaseRequest request) async {
    try { return await _channel.invokeMethod<bool>('releaseMedia', {
      'miniProgramId': request.miniProgramId, 'mediaRef': request.mediaRef,
    }) ?? false; } on MissingPluginException { return false; }
  }
}
''';
